import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.DoCD98hS.js";const b=JSON.parse('{"title":"Core · 加载核心与框架适配","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/core.md","filePath":"modules/catalog/core.md","lastUpdated":1795079257000}'),r={name:"modules/catalog/core.md"};function l(c,e,i,s,n,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="core-·-加载核心与框架适配" tabindex="-1">Core · 加载核心与框架适配 <a class="header-anchor" href="#core-·-加载核心与框架适配" aria-label="Permalink to &quot;Core · 加载核心与框架适配&quot;">​</a></h1><p>统一远程依赖的加载、地址和错误处理，Vue 2、Vue 3、React 只保留组件模型与生命周期的适配差异。</p><div class="info custom-block"><p class="custom-block-title">文档骨架</p><p>先占位目录与已核对的代表性能力，不是完整 API 清单。参数、完整示例和逐文件改造细节待本轮实现定稿后补充；待补项不表示已实现或已发布。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-core</code></td><td>普通工具库与共享构建工具</td></tr><tr><td><code>@melt-js/libs-core-vue2</code></td><td>Vue 2 薄适配</td></tr><tr><td><code>@melt-js/libs-core-vue3</code></td><td>Vue 3 薄适配</td></tr><tr><td><code>@melt-js/libs-core-react</code></td><td>React 薄适配</td></tr></tbody></table><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td><code>preloadHelLibs</code> / <code>loadHelLib</code></td><td>启动预加载与单模块加载，支持 <code>needCompsAutoInstall</code> 自动触发 comps 的 <code>install</code> 钩子</td></tr><tr><td><code>installCompsLib</code></td><td>单独判断并触发组件的 <code>install(Vue)</code>，返回是否注册成功</td></tr><tr><td><code>resolveHelDep</code> / <code>resolveHelDeps</code> / <code>resolveHelHost</code></td><td>依赖描述与托管地址解析</td></tr><tr><td><code>assertHelExports</code> / <code>loadHelComponent</code></td><td>导出校验与组件加载</td></tr><tr><td><code>createHelComponentResource</code> / <code>HelLoadError</code></td><td>共用加载状态与错误模型</td></tr><tr><td><code>showHelLoading</code></td><td>可选启动遮罩，返回清理函数</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td>三个适配包的 <code>defineHelComponent</code></td><td>生成带加载、错误展示和手动重试的框架组件；core 本身不提供 Vue / React 组件</td></tr></tbody></table><h2 id="接入骨架" tabindex="-1">接入骨架 <a class="header-anchor" href="#接入骨架" aria-label="Permalink to &quot;接入骨架&quot;">​</a></h2><p>高频依赖使用 <code>main → preloadHelLibs → import(&quot;./loadApp&quot;)</code>，低频组件通过对应适配包的 <code>defineHelComponent</code> 接入。适配包是普通本地依赖。现有说明见<a href="./../../guide/core.html">核心分层</a>和<a href="./../../guide/loading.html">加载策略</a>。</p><h2 id="待补内容" tabindex="-1">待补内容 <a class="header-anchor" href="#待补内容" aria-label="Permalink to &quot;待补内容&quot;">​</a></h2><ul><li>[ ] 补齐加载配置、返回值、错误阶段与缓存规则。</li><li>[ ] 分别补 Vue 2 / Vue 3 / React 的最小示例、事件与插槽差异。</li><li>[ ] 整理共享脚本、CLI 和公开子路径的用途。</li></ul>',13)])])}const m=t(r,[["render",l]]);export{b as __pageData,m as default};
